def spiral(matrix):
    """Elements of a rectangular matrix in clockwise spiral order from the top-left."""
    out = []
    while matrix:
        out += matrix.pop(0)
        if matrix:
            matrix = [list(r) for r in zip(*matrix)]
    return out
```

