def rle_decode(s):
    """Expand run-length text: 'a3b1c12' -> 'aaab' followed by twelve c's."""
    out = []
    i = 0
    while i < len(s):
        ch = s[i]
        i += 1
        # Read the count digits
        start = i
        while i < len(s) and s[i].isdigit():
            i += 1
        if start == i:
            # No digits found, treat as count of 1
            count = 1
        else:
            count = int(s[start:i])
        out.append(ch * count)
    return "".join(out)
```

