def rle_decode(s):
    """Expand run-length text: 'a3b1c12' -> 'aaab' followed by twelve c's."""
    if not s:
        return ""
    out = []
    i = 0
    while i < len(s):
        ch = s[i]
        i += 1
        # Find the end of the digits following the character
        j = i
        while j < len(s) and s[j].isdigit():
            j += 1
        if j == i:
            # No digits found, treat as a single character with count 1
            count = 1
        else:
            count = int(s[i:j])
        out.append(ch * count)
        i = j
    return "".join(out)
```

