DIGITS = "0123456789abcdefghijklmnopqrstuvwxyz"


def to_base(n, base):
    """Integer n written in the given base (2-36)."""
    if n == 0:
        return "0"
    if n < 0:
        return "-" + to_base(-n, base)
    out = ""
    while n > 0:
        out = DIGITS[n % base] + out
        n //= base
    return out
```

