import re


def parse_duration(text):
    """'1h30m' -> 5400 seconds; also '45s', '2h', '10m5s'."""
    if text is None:
        return None
    pattern = r"^(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$"
    match = re.fullmatch(pattern, text)
    if match is None:
        return None
    h, m, s = match.groups()
    if h is None and m is None and s is None:
        return None
    return int(h or 0) * 3600 + int(m or 0) * 60 + int(s or 0)
