import os


def unique_name(folder, name):
    """A file name in folder that is not taken yet: 'report.txt', then 'report (1).txt', ..."""
    # Split name into base and extension
    if '.' in name and not name.startswith('.'):
        # Find the last dot to handle cases like 'file.name.txt'
        base, ext = name.rsplit('.', 1)
        ext = '.' + ext
    else:
        base = name
        ext = ''

    counter = 1
    while True:
        if counter == 1:
            candidate = f"{base} ({counter}){ext}"
        else:
            candidate = f"{base} ({counter}){ext}"
        full_path = os.path.join(folder, candidate)
        if not os.path.exists(full_path):
            return candidate
        counter += 1
```

